package hu.boltseged.security;
import hu.boltseged.account.*;import hu.boltseged.admin.*;import hu.boltseged.label.*;import hu.boltseged.shipment.*;import org.junit.jupiter.api.*;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.http.MediaType;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.test.web.servlet.MockMvc;import org.springframework.beans.factory.annotation.Autowired;import java.io.*;import java.math.*;import java.time.*;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.authentication;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(controllers={ShipmentController.class,AccountController.class,AdminBillingController.class,BillingSummaryController.class,AdminShipmentController.class})@Import(hu.boltseged.config.SecurityConfig.class)class AuthorizationHttpTest{@Autowired MockMvc mvc;@MockBean ShipmentRepository shipments;@MockBean ShipmentService service;@MockBean ShipmentLabelRepository labels;@MockBean LabelStorage storage;@MockBean AccountRepository accounts;@MockBean org.springframework.security.crypto.password.PasswordEncoder encoder;Account admin=new Account("Admin","admin@test.local","hash","ADMIN"),a=new Account("A","a@test.local","hash","CUSTOMER"),b=new Account("B","b@test.local","hash","CUSTOMER");Shipment sa,sb;@BeforeEach void setup(){sa=shipment(a,"a");sb=shipment(b,"b");sa.price(BigDecimal.ONE,BigDecimal.TWO);sb.price(BigDecimal.ONE,BigDecimal.TWO);when(shipments.findByAccountIdOrderByCreatedAtDesc(a.getId())).thenReturn(List.of(sa));when(shipments.findDetailedById(sa.getId())).thenReturn(Optional.of(sa));when(shipments.findDetailedById(sb.getId())).thenReturn(Optional.of(sb));when(labels.findByShipmentId(any())).thenReturn(List.of());when(accounts.findAll()).thenReturn(List.of(a,b));}private Shipment shipment(Account x,String key){return new Shipment(x,key,"P",LocalDate.now(),"{}","{\"countryCode\":\"HU\"}",List.of(new Shipment.PackageInput(BigDecimal.ONE,BigDecimal.TEN,BigDecimal.TEN,BigDecimal.TEN)));}private UsernamePasswordAuthenticationToken auth(Account x){return new UsernamePasswordAuthenticationToken(x,null,List.of(new SimpleGrantedAuthority("ROLE_"+x.getRole())));}@Test void isolationAndCustomerDto()throws Exception{mvc.perform(get("/api/shipments").with(authentication(auth(a)))).andExpect(status().isOk()).andExpect(jsonPath("$[0].dhlEstimatedCost").doesNotExist()).andExpect(jsonPath("$[0].customerPrice").exists());mvc.perform(get("/api/shipments/"+sa.getId()).with(authentication(auth(a)))).andExpect(status().isOk());mvc.perform(get("/api/shipments/"+sb.getId()).with(authentication(auth(a)))).andExpect(status().isNotFound());mvc.perform(get("/api/shipments/"+sa.getId()).with(authentication(auth(b)))).andExpect(status().isNotFound());}@Test void customerCannotUseAdmin()throws Exception{mvc.perform(get("/api/admin/accounts").with(authentication(auth(a)))).andExpect(status().isForbidden());mvc.perform(get("/api/admin/billing/summary").with(authentication(auth(a)))).andExpect(status().isForbidden());mvc.perform(get("/api/admin/shipments/"+sa.getId()).with(authentication(auth(a)))).andExpect(status().isForbidden());mvc.perform(post("/api/admin/billing/invoice").contentType(MediaType.APPLICATION_JSON).content("[]").with(authentication(auth(a)))).andExpect(status().isForbidden());}@Test void adminCanAccessOtherShipment()throws Exception{mvc.perform(get("/api/admin/accounts").with(authentication(auth(admin)))).andExpect(status().isOk());mvc.perform(get("/api/admin/shipments/"+sb.getId()).with(authentication(auth(admin)))).andExpect(status().isOk());}@Test void labelsAreOwnerOrAdminOnly()throws Exception{ShipmentLabel l=mock(ShipmentLabel.class);when(l.getShipment()).thenReturn(sb);when(l.getStorageKey()).thenReturn("b/key");when(l.getContentType()).thenReturn("application/pdf");when(l.getFileName()).thenReturn("b.pdf");when(labels.findByIdAndShipmentId(any(),eq(sb.getId()))).thenReturn(Optional.of(l));when(storage.get("b/key")).thenReturn(new ByteArrayInputStream("secret".getBytes()));mvc.perform(get("/api/shipments/"+sb.getId()+"/labels/"+UUID.randomUUID()).with(authentication(auth(a)))).andExpect(status().isNotFound());mvc.perform(get("/api/shipments/"+sb.getId()+"/labels/"+UUID.randomUUID()).with(authentication(auth(admin)))).andExpect(status().isOk()).andExpect(content().bytes("secret".getBytes()));}}
